// NEW "HSV" COLOR SCHEME - ADD "/*" BELOW TO DISABLE (YOU CAN ENABLE THE ORIGINAL "RED-GREEN" AT THE BOTTOM)
// Hue represents the direction of a non-linearly scaled (food, catalyst) concentrations vector (red = only food ; green = only catalyst)
// Saturation/Value are mapped from the length of this vector.

#define SATURATION_POW 0.5
#define VALUE_POW 2.8
float sim2hue(vec2 simContents) {
    return mod(atan(
        simContents.r,
        simContents.g+0.01
    )*1.35/3.14+0.31,1.0);
}
vec2 scaleSim(vec2 sim) {
    return pow(sim-vec2(0.01,0.0), vec2(2.0,0.3));
}
// All components are in the range [0…1], including hue.
vec3 hsv2rgb(vec3 c)
{
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}


