/*
Shader responsible for applying the update rules for each pixel at each time step
*/

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float K1 = feedrate/k3;
    float K2 = k2 * feedrate/k3;

    float J1 = feedrate/j3;
    float J2 = j2 * feedrate/j3;



    vec2 pixelSize = 1. / iResolution.xy;
    vec2 uv = fragCoord.xy * pixelSize;

    vec2 h = vec2(pixelSize.x, 0.);
    vec2 v = vec2(0., pixelSize.y);


    bool spacePressed = texture(iChannel1,  vec2(0.126953125, .25)).x > 0.;
    if (iFrame < 10 || spacePressed) { // Init
        fragColor = vec4(1., 0.0, 0.0, 1.0);
        if ( length(uv - vec2(.5,.5)) <= length(1.*pixelSize) ) {
            fragColor+= vec4(0., 0.5, 0., 0.);
        }
        fragColor.g+= channel2Init * texture(iChannel2, uv).x, 0.0 *
                float(texture(iChannel2, uv).x < 0.98); 
    }
    else {  // Sim
        vec4 col = texture(iChannel0, uv);

        vec4 new = vec4(0.0);
        if ( iMouse.z > 0.5 && length((fragCoord.xy - iMouse.xy)*pixelSize) < length(1.*pixelSize) ) {
            if ( texelFetch(iChannel1, ivec2(16, 0), 0).x > 0.) {
                new = vec4(0., 0., 0.2, 1.);
            } else {
                new = vec4(0., 0.2, 0., 1.);
            }
        }

        vec4 inboundFlow;
        inboundFlow.rgb = TAU.rgb / 8. * (   // Algebric inbound diffusion flow
            texture(iChannel0, uv + h) +
            texture(iChannel0, uv - h) +
            texture(iChannel0, uv + v) +
            texture(iChannel0, uv - v) +
            1./1.41*(
                texture(iChannel0, uv + h + v) +
                texture(iChannel0, uv + h - v) +
                texture(iChannel0, uv - h + v) +
                texture(iChannel0, uv - h - v)
            ) -
            4.*(1.+1./1.41)*col
        ).rgb;
        inboundFlow.a = 0.0;


        // Reaction : X + 2X -> 3X
        float reactionSpeed1 = K1*col.x*col.y*col.y;
        float reactionSpeed2 = J1*col.x*col.z*col.z;
        // Concentration variations due to reactions
        vec4 dCol = vec4(
            -reactionSpeed1 - reactionSpeed2 + (feedrate)*(1.-col.x),
            reactionSpeed1 - (K2+feedrate)*col.y - eatrate*col.y*col.z*col.z,
            reactionSpeed2 - (J2+feedrate)*col.z + eatrate*col.y*col.z*col.z,
            -1./float(fireAfter)
        );


        fragColor = clamp(col+dT*(dCol+inboundFlow)+new, 0.0, 1.);
        if (
            fragColor.a > 0.0 && fragColor.a <= 5.0/float(fireAfter) &&
            texture(iChannel2, uv).x <= 0.02
        ) {
            fragColor.b+= 0.01;
        }
    }
}

// You can pick any 2D buffer as iChannel2 in Buffer A to alter the simulation initialization
// The parameter below controls how to scale the pixels from iChannel2 (0.1 should be a good value)
float channel2Init = 0.08;
int fireAfter = 600;

/*
Changing k2 and k3 is the best way to change the behavior of the sim.
See https://itp.uni-frankfurt.de/~gros/StudentProjects/Projects_2020/projekt_schulz_kaefer/
and http://mrob.com/pub/comp/xmorphia/index.html
Mitosis     : k2 = 0.062 ; k3 = 0.028
Solitons    : k2 = 0.060 ; k3 = 0.030
Flowers     : k2 = 0.062 ; k3 = 0.055
Finger      : k2 = 0.060 ; k3 = 0.037
U-Skate     : k2 = 0.061 ; k3 = 0.062
Mazes       : k2 = 0.057 ; k3 = 0.029
Spirals     : k2 = 0.047 ; k3 = 0.014
You can change these values and recompile while the simulation is running
A lot of other combinations produce good results, but some of them just don't work.
Notes for experimenting :
"Fragile" life : k2 = 0.057 ; k3 = 0.016..0.020   ==>  makes "unstable" cells that either split, or die before they get a chance to
*/

